/**
 * Safe development profiler: SELECT 1, GET customer catalogue, optional read-only
 * Drive graph validation, and generated bytes in a temporary file.
 * NEVER calls pg_dump, uploads, stamps receipts, or deletes Drive objects.
 *
 * pnpm --filter @workspace/api-server exec tsx scripts/profile-db-backup-runtime.ts
 * Add --drive for bounded reference validation on real inventory.
 * Add --serial-drive too to reproduce the old serial-read behavior.
 * Add --fixture-drive for a repeatable 83-root comparison without any Drive API.
 * Run with the normal development environment and application workflow running.
 */
import { performance } from "node:perf_hooks";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import { createWriteStream } from "node:fs";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { setTimeout as delay } from "node:timers/promises";
import { monitorEventLoopDelay } from "node:perf_hooks";
import { pool } from "@workspace/db";
import { pacedBackupStream } from "../src/lib/db-backup-throughput";
import { createDriveRetentionStore } from "../src/lib/google-drive-backup-retention-store";
import { planBackupRetention, type RetentionStore } from "../src/lib/google-drive-backup-retention";
import { backupCaptureTime, hasVerifiedBackupReceipt } from "../src/lib/google-drive-backup-policy";
import { retentionProfileFixture } from "./fixtures/backup-retention-profile";

function summary(values: number[]) {
  const ordered = [...values].sort((a, b) => a - b);
  const at = (percentile: number) => Math.round(ordered[Math.min(ordered.length - 1, Math.floor(ordered.length * percentile))] ?? 0);
  return { samples: values.length, p50Ms: at(0.5), p95Ms: at(0.95), maxMs: at(1) };
}

async function profile(label: string, background: () => Promise<unknown>) {
  const api: number[] = [], db: number[] = [];
  let failures = 0, finished = false;
  const lag = monitorEventLoopDelay({ resolution: 10 }); lag.enable();
  const started = performance.now();
  const domain = process.env.REPLIT_DEV_DOMAIN;
  if (!domain) throw new Error("Run in the development workspace with REPLIT_DEV_DOMAIN");
  const work = background().finally(() => { finished = true; });
  void work.catch(() => undefined); // Awaited below after the foreground probe drains.
  let backgroundFailed = false;
  try {
    do {
      await Promise.all([
        (async () => {
          const start = performance.now();
          try {
            const response = await fetch(`https://${domain}/api/products`, { signal: AbortSignal.timeout(10_000) });
            if (!response.ok) throw new Error("Catalogue request failed");
            await response.arrayBuffer();
          } catch { failures++; }
          finally { api.push(performance.now() - start); }
        })(),
        (async () => {
          const start = performance.now();
          try { await pool.query({ text: "SELECT 1", query_timeout: 10_000 }); }
          catch { failures++; }
          finally { db.push(performance.now() - start); }
        })(),
      ]);
      await delay(100);
    } while (!finished);
    await work.catch(error => {
      backgroundFailed = true;
      const message = error instanceof Error && /^(Drive backup retention|Backup folder|No verified|Incomplete legacy)/.test(error.message)
        ? error.message : "Read-only background work failed";
      console.error(message);
    });
  } finally {
    await work.catch(() => undefined); // Do not exit with background reads in flight.
    lag.disable();
  }
  const report = { label, elapsedMs: Math.round(performance.now() - started), api: summary(api), db: summary(db),
    eventLoopP99Ms: Math.round(lag.percentile(99) / 1e6), failures, backgroundFailed };
  console.log(JSON.stringify(report));
  if (failures) throw new Error("Foreground requests failed; profile did not pass");
  if (backgroundFailed) throw new Error("Background profile did not complete");
}

async function driveProfile(serial: boolean) {
  const deadline = Date.now() + 180_000;
  const store = await createDriveRetentionStore(undefined, undefined, { deadline, parallelInventory: !serial });
  const inventory = await store.list();
  console.log(JSON.stringify({ mode: "READ_ONLY", stage: "inventory", serial, files: inventory.length,
    legacyRoots: inventory.filter(f => f.name.endsWith(".SQL.manifest.json")).length, drive: store.metrics?.() }));
  const anchor = inventory.filter(f => hasVerifiedBackupReceipt(f))
    .sort((a, b) => backupCaptureTime(b.name)! - backupCaptureTime(a.name)!)[0];
  if (!anchor) throw new Error("No verified single-file SQL anchor; no mutations performed");
  let tail = Promise.resolve();
  let reads = 0, active = 0, peak = 0;
  const read = async (file: Parameters<RetentionStore["read"]>[0]) => {
    active++; peak = Math.max(peak, active);
    try { reads++; return await store.read(file); } finally { active--; }
  };
  // Serialize only reads to reproduce the old planner's network behavior,
  // leaving the exact same complete graph validation and inventory checks.
  const measured: RetentionStore = { ...store, list: async () => inventory,
    read: file => {
      if (!serial) return read(file);
      const result = tail.then(() => read(file));
      tail = result.then(() => undefined, () => undefined);
      return result;
    } };
  const started = performance.now();
  const plan = await planBackupRetention(measured, anchor, Date.now(), deadline);
  console.log(JSON.stringify({ mode: "READ_ONLY", serial, durationMs: Math.round(performance.now() - started),
    inventoryFiles: inventory.length, manifestReads: reads, peakReads: peak, drive: store.metrics?.(),
    safetyBlocked: plan.skippedLegacy, expiredGenerations: plan.generations.length }));
  if (plan.skippedLegacy) throw new Error("Incomplete legacy graph; deletion remains blocked");
}

async function main() {
  const dir = await mkdtemp(join(tmpdir(), "backup-runtime-profile-"));
  try {
    await profile("idle-baseline", () => delay(10_000));
    if (process.argv.includes("--fixture-drive")) {
      for (const serial of [true, false]) {
        await profile(serial ? "serial-83-root-fixture" : "bounded-83-root-fixture", async () => {
          const fixture = retentionProfileFixture(serial);
          const plan = await planBackupRetention(fixture.store, fixture.anchor, fixture.now);
          if (plan.skippedLegacy || plan.generations.length !== 83) throw new Error("Fixture graph incomplete");
          console.log(JSON.stringify({ serial, ...fixture.metrics(), completeGenerations: plan.generations.length }));
        });
      }
    }
    if (process.argv.includes("--drive")) {
      if (process.argv.includes("--serial-drive")) await profile("serial-drive-read-only", () => driveProfile(true));
      await profile("bounded-drive-read-only", () => driveProfile(false));
    }
    await profile("paced-synthetic-128MiB", async () => {
      const block = Buffer.alloc(64 * 1024, 1);
      const source = Readable.from((function* () { for (let i = 0; i < 2048; i++) yield block; })());
      await pipeline(Readable.from(pacedBackupStream(source)), createWriteStream(join(dir, "synthetic.bin"), { mode: 0o600 }));
    });
  } finally {
    await rm(dir, { recursive: true, force: true });
    await pool.end();
  }
}
main().catch(() => {
  console.error("Backup runtime profile failed (no database dump or Drive mutations performed)");
  process.exitCode = 1;
});
